room.Sequence++;
// 5. Create event
var evt = new GameEventDto(
roomId,
sequence,
"game_over",
new { winner, reason = "resign", resignedBy = playerId }
);
// 6. Broadcast to all players
return (true, null, newState, evt);
```
**Updates are atomic:** All changes in single database transaction

